css:
.btn-first {
  position: relative;
  display: inline-block;
  padding: 2px;
  font-weight: 600;
  color: white;
  background: linear-gradient(
    135deg,
    #000000,
    #4a4a4a,
    #c0c0c0,
    #4a4a4a,
    #000000
  );
  box-shadow:
    0 8px 32px rgba(0, 0, 0, 0.8),
    0 0 16px rgba(192, 192, 192, 0.15);
  cursor: pointer;
  border-radius: 12px;
  border: none;
  transition:
    transform 0.3s ease-in-out,
    box-shadow 0.3s ease;
}

.btn-first:hover {
  transform: scale(1.05);
  box-shadow:
    0 12px 40px rgba(0, 0, 0, 0.9),
    0 0 24px rgba(192, 192, 192, 0.25);
}

.btn-first:active {
  transform: scale(0.95);
}

.btn-first-inner {
  position: relative;
  z-index: 10;
  display: block;
  padding: 12px 24px;
  border-radius: 11px;
  background: linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 50%, #0d0d0d 100%);
  overflow: hidden;
}

.btn-first-content {
  display: flex;
  align-items: center;
  gap: 8px;
}

.btn-first-text-wrap {
  position: relative;
  overflow: hidden;
  height: 1.2em;
  display: flex;
  align-items: center;
}

.btn-first-label-default,
.btn-first-label-hover {
  display: block;
  transition:
    transform 0.4s cubic-bezier(0.4, 0, 0.2, 1),
    opacity 0.4s ease;
  white-space: nowrap;
  color: #e8e8e8;
}

.btn-first-label-default {
  transform: translateY(0);
  opacity: 1;
}

.btn-first-label-hover {
  position: absolute;
  left: 0;
  transform: translateY(100%);
  opacity: 0;
  color: #c0c0c0;
}

.btn-first:hover .btn-first-label-default {
  transform: translateY(-100%);
  opacity: 0;
}

.btn-first:hover .btn-first-label-hover {
  transform: translateY(0);
  opacity: 1;
}

.btn-first-icon {
  width: 24px;
  height: 24px;
  transition: transform 0.5s;
  flex-shrink: 0;
  color: #c0c0c0;
}

.btn-first:hover .btn-first-icon {
  transform: translateX(4px);
}
